package com.autoops.common.error;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("code","VALIDATION_FAILED","message",e.getMessage(),"timestamp",Instant.now().toString()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> invalid(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("code","REQUEST_INVALID","message","Request validation failed","timestamp",Instant.now().toString()));}}
